import {ReviewInbox} from './ReviewInbox.jsx';
import {useWritingRequest} from './writing-request.js';
import {useModules} from '../modules/context.tsx';
import React,{useState} from 'react';
import {Modal} from './preferences.tsx';
import {useResource,useDraft} from './state.js';
import {ResourceState,SaveBar} from './ui.jsx';
import {DocumentTextarea} from './workspace.tsx';
export function ChapterMaterials({call,novelId,chapter,selection='',dirty,busy,run,close,onMemory,onEvent}){
 const modules=useModules();
 const write=useWritingRequest(call);
 const [reviewOpen,setReviewOpen]=useState(false);const [poll,setPoll]=useState(0),[query,setQuery]=useState(''),[serverError,setServerError]=useState('');
 const resource=useResource(()=>Promise.all([call('writing.link.list',{novelId,chapterId:chapter.id}),call('writing.link.candidates',{novelId,chapterId:chapter.id}),call('graph.list',{novelId}),modules.foreshadow?call('writing.foreshadow.list',{novelId,chapterId:chapter.id}):Promise.resolve([]),modules.timeline?call('writing.event.list',{novelId,chapterId:chapter.id}):Promise.resolve([])]),[call,novelId,chapter.id,poll,modules]);
 const initial={nodeId:'',kind:'appearance',evidence:selection,chapterRevision:chapter.revision},draft=useDraft(`${novelId}:chapter-materials:${chapter.id}`,initial),v=draft.value;
 const set=(key,value)=>draft.change(old=>({...old,[key]:value}));
 const save=()=>run(async()=>{setServerError('');try{await write('writing.link.create',{novelId,chapterId:chapter.id,nodeId:v.nodeId,kind:v.kind,evidence:v.evidence,expectedChapterRevision:v.chapterRevision,confirmed:true,reason:'作者确认本章资料'});draft.accept({...initial,evidence:''});setPoll(n=>n+1);}catch(e){setServerError(e.message);throw e;}});
 return <Modal title="本章资料" close={close} className="chapter-materials-modal"><p>{chapter.title} · 已保存版本 {chapter.revision}</p>{dirty&&<p className="notice">正文仍有未保存修改。先返回正文保存，再记录正式关联。</p>}<ResourceState resource={resource}>{resource.value&&(()=>{const [links,candidates,nodes,foreshadows,events]=resource.value,node=nodes.find(n=>n.id===v.nodeId);return <>
 <details onToggle={e=>setReviewOpen(e.currentTarget.open)}><summary>本章整理建议</summary>{reviewOpen&&<ReviewInbox {...{call,novelId,chapter,busy,run,dirty}}/>}</details>{modules.timeline&&<><h3>本章事件</h3>{events.length?events.map(e=><p key={e.id}><button onClick={()=>{close();onEvent?.(e.id);}}>{e.title}</button> · {e.storyTime||'时间未注明'}{e.review?' · 正文依据需复核':''}</p>):<p className="muted">尚未关联事件，可在时间线编辑章节呈现。</p>}</>}
 <h3>已确认关联</h3>{links.length?links.map(l=><div key={l.id} className="structure-entry"><button onClick={()=>{close();onMemory(l.nodeId);}}>{l.nodeName}</button> · {{appearance:'实际出场',mention:'仅被提及',reference:'资料关联'}[l.kind]}<small> · 版本 {l.chapterRevision}{l.review?' · 需复核':''}{l.excluded?' · 已删除资料':''}</small>{l.manual?<p className="muted">作者指定出场</p>:<blockquote>{l.evidence}</blockquote>}<button disabled={busy} onClick={()=>run(async()=>{await call('writing.link.delete',{novelId,id:l.id,expectedRevision:l.revision,reason:'作者移除章节关联'});setPoll(n=>n+1);})}>移除关联</button></div>):<p className="muted">尚未确认本章资料。</p>}
 <h3>添加关联</h3><div className="structure-form"><label>搜索资料<input aria-label="搜索本章资料" value={query} onChange={e=>setQuery(e.target.value)}/></label><label>资料<select aria-label="关联资料" value={v.nodeId} onChange={e=>{const node=nodes.find(n=>n.id===e.target.value);draft.change(old=>({...old,nodeId:e.target.value,kind:node?.type==='character_card'?'appearance':'reference'}));}}><option value="">选择角色或世界资料</option>{nodes.filter(n=>!query||[n.name,...n.aliases||[]].some(name=>name.includes(query))).map(n=><option key={n.id} value={n.id}>{n.name} · {n.type==='character_card'?'角色':'世界'}</option>)}</select></label><label>关联类型<select aria-label="本章关联类型" value={v.kind} onChange={e=>set('kind',e.target.value)}>{node?.type==='character_card'?<><option value="appearance">实际出场</option><option value="mention">仅被提及</option></>:<option value="reference">资料关联</option>}</select></label><label>已保存正文依据<DocumentTextarea aria-label="关联正文依据" value={v.evidence} onChange={e=>set('evidence',e.target.value)}/></label></div><SaveBar dirty={!!v.nodeId&&!!v.evidence.trim()} {...{busy}} error={serverError||draft.cacheError} invalid={dirty?'请先保存正文':null} onSave={save} label="确认并记录关联"/>
 <details><summary>姓名／别名匹配候选（{candidates.items.length}）</summary><p className="muted">候选不会自动成为出场记录；同名可能匹配多条资料，请明确选择实际出场或仅被提及。</p>{candidates.items.map(c=><div key={c.nodeId} className="structure-entry"><strong>{c.name}</strong><blockquote>{c.evidence}</blockquote><button disabled={busy||dirty} onClick={()=>draft.change(old=>({...old,nodeId:c.nodeId,kind:c.type==='character_card'?'appearance':'reference',evidence:c.evidence,chapterRevision:c.chapterRevision}))}>填入候选，等待确认</button></div>)}</details>
 {foreshadows.filter(f=>f.due||f.evidence.some(e=>e.chapterId===chapter.id)).length>0&&<><h3>本章伏笔提醒</h3>{foreshadows.filter(f=>f.due||f.evidence.some(e=>e.chapterId===chapter.id)).map(f=><p className={f.due?'notice':''} key={f.id}>{f.title}{f.due?' · 已到计划回收章，尚未回收':''}{f.review?' · 依据需复核':''}</p>)}</>}
 </>;})()}</ResourceState></Modal>;
}
